// The on-chain shapes canary-claims reads and writes.
// Full registry ABI: contracts/out/CanaryRegistry.abi.json (generated by `npm run compile` in /contracts).
import { parseAbiParameters } from 'viem'

/** Uniswap V2 pair: token0() tells which side of a Swap event is the case's token. */
export const UniswapV2Pair = [
	{
		type: 'function',
		name: 'token0',
		inputs: [],
		outputs: [{ name: '', type: 'address' }],
		stateMutability: 'view',
	},
] as const

/** keccak256("Transfer(address,address,uint256)"): topics = [sig, from, to], data = value */
export const TRANSFER_TOPIC = '0xddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef'
/** keccak256("Swap(address,uint256,uint256,uint256,uint256,address)") on a Uniswap V2 pair:
 *  topics = [sig, sender, to], data = (amount0In, amount1In, amount0Out, amount1Out) */
export const SWAP_TOPIC = '0xd78ad95fa46c994b6551d0da85fc275fe613ce37657fb8d5e3d130840159d822'
export const SwapDataParams = parseAbiParameters(
	'uint256 amount0In, uint256 amount1In, uint256 amount0Out, uint256 amount1Out',
)

export const CanaryRegistry = [
	{
		type: 'function',
		name: 'claimVerifiedAt',
		inputs: [
			{ name: 'caseId', type: 'bytes32' },
			{ name: 'evidenceHash', type: 'bytes32' },
		],
		outputs: [{ name: '', type: 'uint64' }],
		stateMutability: 'view',
	},
] as const

// Report envelope expected by CanaryRegistry.onReport: abi.encode(uint8 kind, bytes body)
export const REPORT_CLAIM_VERIFIED = 3
export const ReportEnvelopeParams = parseAbiParameters('uint8 kind, bytes body')
export const ClaimVerifiedBodyParams = parseAbiParameters(
	'bytes32 caseId, bytes32 evidenceHash, bytes32 claimantRef, bytes32 walletRef, uint32 purchases, uint64 firstBuyBlock',
)
